#include <Cellerator/compiler/reflection/implement_inline_semantic_ir_blocks_v1.hh>
namespace cellerator::compiler::reflection::v1 {
inline_semantic_status_v1 validate_inline_semantic_block_v1(const inline_semantic_block_v1&b)noexcept{if(!validate_reflected_operation_v1(b.replacement))return inline_semantic_status_v1::invalid_operation;if(b.surrounding_field.empty()||b.profile_state.empty()||b.captures.empty()||b.results.empty())return inline_semantic_status_v1::missing_context;for(const auto&c:b.captures)if(c.value.domain!=b.replacement.relation.source_domain)return inline_semantic_status_v1::domain_mismatch;for(const auto&r:b.results)if(r.value.domain!=b.replacement.relation.target_domain)return inline_semantic_status_v1::domain_mismatch;if(b.captures.front().value.generation!=b.replacement.relation.value_generation)return inline_semantic_status_v1::generation_mismatch;if(b.replacement.effects==reflected_effect_v1::none)return inline_semantic_status_v1::effect_mismatch;return inline_semantic_status_v1::valid;}
}
